$:/plugins/huwiki/site-publisher/layouts.text:
/* HUWiki Forge – Modern. Airy, blue-toned, distraction-free reading. */
body.husp-layout-modern{--ink:#223753;--line:#d7e3ef;--sea:#245a8e;--background:#edf3f9;background:var(--background);color:var(--ink)}
body.husp-layout-modern .top{background:#fff;box-shadow:0 2px 14px #19365b12;border-bottom:1px solid #ccdeeb}
body.husp-layout-modern .booktitle{font-size:19px;letter-spacing:-.02em}
body.husp-layout-modern .hamb,body.husp-layout-modern #nav-pin{color:var(--sea);background:#f8fbff;border-color:#c3d6ea}
body.husp-layout-modern nav{background:#fff;border-color:#d4e1eb;box-shadow:0 15px 40px #1d426b22}
body.husp-layout-modern nav button.chapter.selected{background:#e0ecfb;color:#214d7d}
body.husp-layout-modern #article-view{background:#fff;box-shadow:0 7px 30px #183f6415}
body.husp-layout-modern #article-view h1{font-family:system-ui,sans-serif;font-weight:750;letter-spacing:-.045em;color:#213e66}
body.husp-layout-modern .prose h2,body.husp-layout-modern .prose h3{color:#275b91;line-height:1.25}
body.husp-layout-modern .prose{font-size:17px;line-height:1.78;color:#26384e}
body.husp-layout-modern .prose a{color:#2463a6}
body.husp-layout-modern #focus-toggle{color:var(--sea);border-color:#c3d6ea}
body.husp-layout-modern.husp-focus #article-view{box-shadow:none}

/* HUWiki Forge – Retro. Warm paper, double rules and classic typography. */
body.husp-layout-retro{--ink:#433024;--line:#c7a987;--sea:#8b3554;--background:#f5ebd6;background:var(--background);color:var(--ink)}
body.husp-layout-retro .top{background:#faefdb;border-bottom:3px double #a66b53}
body.husp-layout-retro .booktitle{font:700 19px Georgia,"Times New Roman",serif;color:#6a2b46}
body.husp-layout-retro .hamb,body.husp-layout-retro #nav-pin{color:#7a3249;background:#fff8eb;border-color:#c19c72;border-radius:3px}
body.husp-layout-retro nav{background:#fff5e3;border:2px double #c89c71;border-radius:5px}
body.husp-layout-retro nav button.chapter.selected{background:#efdbc6;color:#723145}
body.husp-layout-retro #article-view{background:#fff9ed;border-left:4px double #c59b75;border-right:4px double #c59b75;box-shadow:0 6px 22px #4930201b}
body.husp-layout-retro #article-view h1{font:700 clamp(27px,3vw,39px)/1.25 Georgia,"Times New Roman",serif;color:#773451}
body.husp-layout-retro .prose{font:17px/1.78 Georgia,"Times New Roman",serif;color:#432f25}
body.husp-layout-retro .prose h2,body.husp-layout-retro .prose h3{font-family:Georgia,"Times New Roman",serif;color:#783751}
body.husp-layout-retro .prose a{color:#8b3554}
body.husp-layout-retro #focus-toggle{color:#783751;background:#fff8eb;border-color:#c19c72}
body.husp-layout-retro.husp-focus #article-view{border:0;box-shadow:none}

/* HUWiki Forge – HUPedia. Encyclopedia reading shell; infobox markup/CSS still comes from the HUPedia plugin. */
body.husp-layout-hupedia{--ink:#202122;--line:#a2a9b1;--sea:#365fa0;--background:#f8f9fa;background:var(--background);color:var(--ink)}
body.husp-layout-hupedia .top{background:#fff;border-top:4px solid #274b76;border-bottom:1px solid #c8ccd1}
body.husp-layout-hupedia .booktitle{font:700 21px Georgia,"Times New Roman",serif;color:#202122}
body.husp-layout-hupedia .hamb,body.husp-layout-hupedia #nav-pin{background:#f8f9fa;border:1px solid #a2a9b1;border-radius:3px;color:#365fa0}
body.husp-layout-hupedia nav{background:#f8f9fa;border:1px solid #a2a9b1;border-radius:4px}
body.husp-layout-hupedia nav button.chapter.selected{background:#dbe6f2;color:#202122}
body.husp-layout-hupedia #article-view{background:#fff;border:1px solid #c8ccd1;box-shadow:none}
body.husp-layout-hupedia #article-view h1{font:700 clamp(26px,3vw,38px)/1.22 Georgia,"Times New Roman",serif;color:#202122;border-bottom:1px solid #a2a9b1;padding-bottom:.4em}
body.husp-layout-hupedia .prose{font:16px/1.7 system-ui,-apple-system,sans-serif;color:#202122}
body.husp-layout-hupedia .prose h2{font:600 1.55em Georgia,serif;border-bottom:1px solid #a2a9b1;padding-bottom:.18em}
body.husp-layout-hupedia .prose h3{font-family:Georgia,serif;font-weight:600}
body.husp-layout-hupedia .prose a{color:#365fa0}
body.husp-layout-hupedia #focus-toggle{background:#f8f9fa;border-color:#a2a9b1;color:#365fa0}
body.husp-layout-hupedia.husp-focus #article-view{border:0;box-shadow:none}
@media(max-width:750px){body.husp-layout-hupedia .hupedia-infobox{float:none;max-width:100%;width:100%;margin:0 0 1.2rem}}

/* HUWiki Forge – Vanilla. Restrained, classic TiddlyWiki-inspired reading shell. */
body.husp-layout-vanilla{--ink:#303030;--line:#dedede;--sea:#56647a;--background:#f7f7f7;background:var(--background);color:var(--ink)}
body.husp-layout-vanilla .top{background:#fff;border-bottom:1px solid #dedede}
body.husp-layout-vanilla .booktitle{font:600 19px system-ui,sans-serif;color:#383838}
body.husp-layout-vanilla .hamb,body.husp-layout-vanilla #nav-pin{color:#4c617d;background:#fff;border-radius:5px;border-color:#c9ced5}
body.husp-layout-vanilla nav{background:white;border-radius:4px;border-color:#dedede;box-shadow:0 7px 22px #00000015}
body.husp-layout-vanilla nav button.chapter.selected{background:#e9edf4;color:#303f57}
body.husp-layout-vanilla #article-view{background:#fff;border:1px solid #e7e7e7;box-shadow:0 1px 5px #0000000c}
body.husp-layout-vanilla #article-view h1{font:600 clamp(26px,3vw,34px)/1.3 system-ui,sans-serif;color:#333}
body.husp-layout-vanilla .prose{font:16px/1.7 system-ui,-apple-system,sans-serif;color:#343434}
body.husp-layout-vanilla .prose h2,body.husp-layout-vanilla .prose h3{color:#3c4858}
body.husp-layout-vanilla .prose a{color:#325ca4}
body.husp-layout-vanilla.husp-focus #article-view{border:0;box-shadow:none}

$:/plugins/huwiki/site-publisher/cutout/.text:
/* CutOut site reader, from OAuthLab CutOutSiteRuntime.js; self-contained. */
.huw-site-cutout{margin:1.2em auto;max-width:100%;min-width:0}
.huw-site-cutout svg{display:block;width:100%;height:auto;background:transparent}
.huw-cutout-controls{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:8px 0;font:13px/1.5 system-ui}
.huw-cutout-controls button{cursor:pointer;border:1px solid #b9c5d1;border-radius:6px;padding:6px 10px;background:#fff;color:#20374b;touch-action:manipulation;min-height:38px}
.huw-cutout-controls button:focus-visible{outline:2px solid #08785e;outline-offset:2px}
.huw-cutout-controls input[type=range]{flex:1;min-width:90px;max-width:280px;touch-action:pan-y}
.husp-site-image,.husp-site-media{margin:1em auto;max-width:100%}
.husp-site-image img{display:block;max-width:100%;height:auto;margin:auto}
.husp-site-media audio,.husp-site-media video{max-width:100%;width:min(100%,850px)}
.husp-site-media figcaption{font-size:.82em;color:#64716b;margin-top:7px}

$:/plugins/huwiki/site-publisher/drawing.text:
/* HUWiki Forge: SVG drawings from the installed Excalidraw renderer. */
.huw-site-drawing{max-width:100%;margin:1em auto;padding:0;line-height:0}
.huw-site-drawing img{display:block;max-width:100%;height:auto;object-fit:contain;margin:0 auto}
.prose .huw-site-drawing{overflow:visible}
@media print{.huw-site-drawing img{max-height:95vh;page-break-inside:avoid}}
